#!/usr/bin/env python3
"""Build a self-contained, local research browser from the compiled ledger."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
payload={k:json.loads((root/'data'/f'{k}.json').read_text()) for k in ['cases','claims','sources','graph','comparisons','validation']}
jsdata=json.dumps(payload,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
html=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Technology in use · Research atlas</title>
<style>
:root{--ink:#192e3a;--muted:#536570;--paper:#f5f3ed;--white:#fff;--line:#cfd7d8;--accent:#075a70;--pale:#e7eff0;--warn:#865b12}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,-apple-system,sans-serif}header{padding:40px max(28px,5vw) 25px;border-bottom:1px solid var(--line)}.kicker{text-transform:uppercase;letter-spacing:.12em;font-size:12px;font-weight:700;color:var(--accent)}h1{font:clamp(32px,5vw,52px)/1.12 Georgia,serif;margin:12px 0}h2{font:30px/1.2 Georgia,serif;margin:8px 0 18px}h3{font-size:18px;margin:26px 0 12px}h4{font-size:15px;margin:0 0 6px}p{margin:0 0 14px}a{color:var(--accent);text-underline-offset:3px}nav{display:flex;flex-wrap:wrap;gap:10px 24px;margin-top:22px}.intro{max-width:850px;color:var(--muted)}.metrics{display:flex;flex-wrap:wrap;gap:18px;margin-top:20px;font-size:14px}.metrics b{font-size:20px}.layout{display:grid;grid-template-columns:minmax(280px,350px) minmax(0,1fr);max-width:1600px;margin:auto}.sidebar{border-right:1px solid var(--line);padding:26px 22px;align-self:start;position:sticky;top:0;max-height:100vh;overflow:auto}.detail{padding:34px clamp(24px,4vw,70px) 70px;max-width:1100px}.controls{display:grid;gap:12px;margin-bottom:18px}label{display:block;font-size:13px;font-weight:700;margin-bottom:5px}input,select{width:100%;background:white;border:1px solid #899ba2;border-radius:4px;padding:10px;color:var(--ink);font:inherit;font-size:14px}input:focus,select:focus,button:focus-visible{outline:3px solid #d3a52f;outline-offset:2px}.case-button{display:block;width:100%;text-align:left;border:0;border-top:1px solid var(--line);background:transparent;padding:15px 9px;cursor:pointer;color:var(--ink);font:inherit}.case-button:hover{background:#eceded}.case-button[aria-current=true]{background:var(--pale);border-left:4px solid var(--accent);padding-left:5px}.case-id{font-size:11px;font-weight:700;letter-spacing:.04em;color:var(--accent)}.case-title{display:block;font-weight:650;font-size:14px;line-height:1.35}.case-period{font-size:12px;color:var(--muted)}.count{font-size:12px;color:var(--muted);margin-bottom:10px}.tag{display:inline-block;background:var(--pale);padding:3px 8px;font-size:12px;margin:0 6px 6px 0;border-radius:3px}.scope{background:#fff;border-left:4px solid var(--accent);padding:18px 20px;margin:20px 0}.small{font-size:13px;color:var(--muted)}.caution{border-left-color:var(--warn);background:#fffaf0}dl{margin:0}dt{font-size:13px;font-weight:700;color:var(--muted);margin-top:14px;text-transform:capitalize}dd{margin:4px 0 10px}details{border-top:1px solid var(--line);padding:12px 0}summary{cursor:pointer;font-weight:650;font-size:15px}details p{margin-top:12px}.claim{padding:16px 0;border-top:1px solid var(--line)}.claim-id{color:var(--accent);font-size:12px;font-weight:700}.evidence{margin:12px 0;padding:0 0 0 20px;font-size:14px}.evidence li{margin-bottom:8px}.edge{background:#fff;padding:16px;margin:12px 0;border:1px solid var(--line)}.relation{color:var(--accent);font-weight:700;font-size:13px;margin:5px 0}.empty{padding:35px 0;color:var(--muted)}.subnav{display:flex;gap:15px;flex-wrap:wrap;font-size:13px;margin:25px 0}footer{border-top:1px solid var(--line);padding:22px 5vw;color:var(--muted);font-size:12px}.mode-note{margin:15px 0 0;max-width:900px;font-size:13px}.visually-hidden{position:absolute;clip:rect(0,0,0,0);height:1px;width:1px;overflow:hidden}@media(max-width:800px){.layout{display:block}.sidebar{position:static;max-height:450px;border-right:0;border-bottom:1px solid var(--line)}.detail{padding:28px 22px}.metrics{gap:12px}header{padding:28px 22px}.case-button{padding:12px 6px}}@media print{.sidebar,nav,.subnav{display:none}.layout{display:block}.detail{padding:20px}details{display:block}header{padding:20px}body{background:white}}
</style></head><body>
<header><div class="kicker">Big Idea · Research edition 1 · 5 November 2026</div><h1>Technology in use</h1><p class="intro">A comparative history of how working objects become operating systems—and why people, institutions and environments produce different patterns of use.</p><div class="metrics" id="metrics"></div><p class="mode-note">A purposive, reviewed research collection. Counts describe the collection, not historical prevalence or independent confirmations. Source access, rival explanations and unresolved questions remain visible.</p><nav aria-label="Reading routes"><a href="README.md">Start here</a><a href="analysis/SYNTHESIS.md">Synthesis</a><a href="analysis/GLOBAL_MAP.md">Chronological map</a><a href="analysis/FUTURE_ROLES.md">Human roles: conditional implications</a><a href="reviews/RESPONSE_LOG.md">Criticism and repairs</a><a href="data/graph.json">Graph data</a></nav></header>
<main class="layout"><aside class="sidebar" aria-label="Find cases"><div class="controls"><div><label for="search">Search cases, actors and mechanisms</label><input id="search" type="search" placeholder="e.g. maintenance, Ghana, printing"></div><div><label for="strand">Research strand</label><select id="strand"><option value="">All strands</option></select></div></div><div class="count" id="count" role="status" aria-live="polite"></div><div id="case-list"></div></aside><article class="detail" id="detail" aria-live="polite"></article></main>
<footer>This browser is generated from the JSON ledgers. It makes no external requests and needs no account. Read the narrative dossiers for fuller arguments; inspect claims before reusing graph links. No transitive causal closure across cases is warranted.</footer>
<script id="research-data" type="application/json">__DATA__</script><script>
'use strict';
const d=JSON.parse(document.getElementById('research-data').textContent);
const byId={cases:Object.fromEntries(d.cases.map(x=>[x.id,x])),claims:Object.fromEntries(d.claims.map(x=>[x.id,x])),sources:Object.fromEntries(d.sources.map(x=>[x.id,x])),nodes:Object.fromEntries(d.graph.nodes.map(x=>[x.id,x]))};
const el=id=>document.getElementById(id);const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=x=>Array.isArray(x)?x.map(val).join('; '):x&&typeof x==='object'?Object.entries(x).map(([k,v])=>k.replaceAll('_',' ')+': '+val(v)).join(' · '):String(x??'');
const pairs=o=>'<dl>'+Object.entries(o||{}).map(([k,v])=>'<dt>'+h(k.replaceAll('_',' '))+'</dt><dd>'+h(val(v))+'</dd>').join('')+'</dl>';
const link=(u,label)=>'<a href="'+h(u)+'"'+(/^https?:/.test(u)?' target="_blank" rel="noopener noreferrer"':'')+'>'+h(label)+'</a>';
const tags=a=>(a||[]).map(x=>'<span class="tag">'+h(x)+'</span>').join('');
const strandNames={MAT:'Materials and metallurgy',ANC:'Ancient infrastructure',NET:'Knowledge and navigation',IND:'Industrial production',AGR:'Agriculture and households',MED:'Health and public goods',MOB:'Transport and large systems',DIG:'Digital and consumer systems',LBR:'Labour transitions',OCE:'Indigenous and Oceanian systems',POL:'State, military and administration',SKL:'Precision, repair and skills',PSY:'Behaviour, identity and access',ENE:'Energy and manufacturing'};
const counts=d.validation.counts;
el('metrics').innerHTML=[['cases',counts.cases],['evidence claims',counts.claims],['source records',counts.sources],['scoped graph edges',counts.edges]].map(([k,v])=>'<span><b>'+h(v)+'</b> '+h(k)+'</span>').join('');
for(const s of [...new Set(d.cases.map(x=>x.contribution))].sort()){const opt=document.createElement('option');opt.value=s;opt.textContent=s+' · '+(strandNames[s]||s);el('strand').append(opt)}
let selected=decodeURIComponent(location.hash.slice(1));if(!byId.cases[selected])selected=d.cases[0]?.id;
function renderList(){const q=el('search').value.toLowerCase().trim().split(/\s+/).filter(Boolean),strand=el('strand').value;const cases=d.cases.filter(c=>(!strand||c.contribution===strand)&&q.every(t=>JSON.stringify(c).toLowerCase().includes(t)));el('count').textContent=cases.length+' of '+d.cases.length+' cases';el('case-list').replaceChildren();for(const c of cases){const b=document.createElement('button');b.className='case-button';b.setAttribute('aria-current',String(c.id===selected));b.innerHTML='<span class="case-id">'+h(c.id)+'</span><span class="case-title">'+h(c.title)+'</span><span class="case-period">'+h(c.period)+'</span>';b.addEventListener('click',()=>{selected=c.id;history.replaceState(null,'','#'+c.id);renderDetail();renderList()});el('case-list').append(b)}if(!cases.length)el('case-list').innerHTML='<p class="empty">No cases match these filters. Try a broader term.</p>'}
function renderDetail(){const c=byId.cases[selected];if(!c){el('detail').innerHTML='<p class="empty">No completed cases are available.</p>';return}const claims=c.claim_ids.map(id=>byId.claims[id]).filter(Boolean),edges=d.graph.edges.filter(e=>e.case_ids.includes(c.id)),comparisons=d.comparisons.filter(x=>x.case_ids.includes(c.id));
let out='<div class="kicker">'+h(c.id)+' · '+h(strandNames[c.contribution]||c.contribution)+'</div><h2>'+h(c.title)+'</h2><p class="small">'+h(c.period)+' · '+h(c.region.join('; '))+'</p>'+tags(c.outcome)+'<p>'+h(c.summary)+'</p><p>'+link('contributions/'+c.contribution+'/report.md','Read the substantive research dossier')+'</p><nav class="subnav" aria-label="Case sections"><a href="#episode">Episode and actors</a><a href="#stages">Stages</a><a href="#evidence">Evidence and rivals</a><a href="#relations">Graph relations</a><a href="#comparisons">Comparisons</a></nav>';
out+='<section id="episode"><h3>What was actually observed?</h3><div class="scope">'+pairs(c.episode)+'</div><details><summary>Who chose, paid, worked and could refuse?</summary>'+pairs(c.actors)+'</details><details><summary>Tasks, livelihoods and entry barriers</summary>'+pairs(c.labour)+'</details></section>';
out+='<section id="stages"><h3>Stages and outcomes</h3>'+pairs(c.stages)+'<div class="scope caution"><h4>Counterevidence and limits</h4><p>'+h(val(c.counterevidence))+'</p></div></section>';
out+='<section id="evidence"><h3>Evidence and rival explanations</h3>';
for(const k of claims){out+='<div class="claim"><span class="claim-id">'+h(k.id)+'</span><p>'+h(k.statement)+'</p>'+tags([k.confidence+' confidence',k.causal_status,k.evidence_type])+'<ul class="evidence">';for(const ref of k.sources){const s=byId.sources[ref.source_id];if(s)out+='<li>'+link(s.url,s.id+' · '+s.title)+'<br><span class="small">'+h(ref.locator)+' · '+h(s.access)+'</span><br>'+h(ref.supports)+'</li>'}out+='</ul><details><summary>Test, strongest rival and remaining ambiguity</summary>'+pairs(k.test)+'<p><b>Counterevidence:</b> '+h(val(k.counterevidence))+'</p><p><b>Inference limit:</b> '+h(val(k.inference_limits))+'</p></details></div>'}out+='</section>';
out+='<section id="relations"><h3>Scoped graph relations</h3><p class="small">These are typed relationships within stated episodes. Multiple inputs do not imply joint necessity; a path across different cases is not proof of causation.</p>';
for(const e of edges){out+='<div class="edge"><div class="claim-id">'+h(e.id)+' · '+h(e.confidence)+' confidence</div><strong>'+h(byId.nodes[e.from]?.label||e.from)+'</strong><div class="relation">'+h(e.relation)+' →</div><strong>'+h(byId.nodes[e.to]?.label||e.to)+'</strong><p class="small">Basis: '+h(e.basis)+' · '+h(val(e.scope))+'</p><p>'+h(e.qualification)+'</p><details><summary>Alternatives, necessity and dispute</summary>'+pairs({alternatives:e.alternatives,joint_inputs:e.joint_inputs,necessity_rationale:e.necessity_rationale,dispute:e.dispute,claims:e.claim_ids,sources:e.source_ids})+'</details></div>'}if(!edges.length)out+='<p class="small">No graph edges are asserted for this case.</p>';out+='</section>';
out+='<section id="comparisons"><h3>Why these comparisons?</h3>';for(const x of comparisons)out+='<details><summary>'+h(x.id)+' · '+h(x.question)+'</summary>'+pairs(x)+'</details>';if(!comparisons.length)out+='<p class="small">No structured comparison is attached to this case.</p>';out+='</section><h3>Source access and lineage</h3>';
for(const sid of c.source_ids){const s=byId.sources[sid];if(s)out+='<details><summary>'+h(sid)+' · '+h(s.title)+'</summary><p>'+link(s.url,'Open source')+'</p>'+pairs({authors:s.authors,year:s.year,access:s.access,inspected:s.locator,scope_limit:s.scope_limit,evidence_lineage:s.evidence_lineage})+'</details>'}el('detail').innerHTML=out;
}
el('search').addEventListener('input',renderList);el('strand').addEventListener('change',renderList);window.addEventListener('hashchange',()=>{const id=decodeURIComponent(location.hash.slice(1));if(byId.cases[id]){selected=id;renderDetail();renderList()}});renderList();renderDetail();
</script></body></html>'''
(root/'index.html').write_text(html.replace('__DATA__',jsdata))
print('Wrote',root/'index.html')
